class TokenBucket:
    def __init__(self, cap, rate):
        self.cap, self.rate, self.tokens = cap, rate, cap
        self.last, self.lock = time.monotonic(), threading.Lock()
    def allow(self):
        with self.lock:
            now = time.monotonic()
            self.tokens = min(self.cap, self.tokens + (now - self.last) * self.rate)
            self.last = now
            if self.tokens >= 1:
                self.tokens -= 1
                return True
            return False

